from pathlib import Path

p=Path('app/src/main/assets/index.html')
s=p.read_text(encoding='utf-8')
if 'KPC_V22' in s: raise SystemExit('V2.2 patch already applied')
css='''<style id="kpc-v22-style">#installBtn{display:none!important}#kpcV22Modal{position:fixed;inset:0;z-index:2147483647;background:#061426;color:#fff;padding:20px;overflow:auto}#kpcV22Modal .box{max-width:620px;margin:5vh auto;background:#101a30;border:1px solid #d9b44a;border-radius:16px;padding:20px}#kpcV22Modal input{width:100%;box-sizing:border-box;margin:6px 0 12px;padding:11px;border-radius:8px;border:1px solid #777}#kpcV22Modal button{background:#0b1b3b;color:#d9b44a;border:1px solid #d9b44a;border-radius:10px;padding:10px 14px;font-weight:700}.hand,.user{border-bottom:1px solid #555;padding:12px 0}.muted{opacity:.75;font-size:.9em}.err{color:#ffb3b3}</style>'''
js=r'''<script>window.KPC_V22=true;(()=>{const U='https://xfutvyvvhlhpeowtgfbq.supabase.co',K='__KPC_SUPABASE_PUBLISHABLE_KEY__',S='kpc_v22_session';let session=null,prof=null;const $=id=>document.getElementById(id),e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function modal(h){let m=$('kpcV22Modal');if(!m){m=document.createElement('div');m.id='kpcV22Modal';document.body.appendChild(m)}m.innerHTML='<div class="box">'+h+'</div>';return m}const close=()=>$('kpcV22Modal')?.remove();async function api(path,o={}){let h={'apikey':K,'Content-Type':'application/json',...(o.headers||{})};if(session?.access_token)h.Authorization='Bearer '+session.access_token;let r=await fetch(U+path,{...o,headers:h}),d=null;try{d=await r.json()}catch{}if(!r.ok)throw Error(d?.msg||d?.message||d?.error_description||'Erreur '+r.status);return d}function store(x){session=x;localStorage.setItem(S,JSON.stringify(x))}async function profile(){return (await api('/rest/v1/profiles?select=id,display_name,approved,role&id=eq.'+encodeURIComponent(session.user.id)))?.[0]}async function approved(){prof=await profile();if(!prof)throw Error('Profil KPC introuvable.');if(!prof.approved)throw Error('Compte en attente de validation par un administrateur.');return prof}function signup(){modal('<h2>Créer mon compte KPC</h2><p>Crée ton compte personnel. Il devra ensuite être validé par un administrateur du club.</p><label>Pseudo / nom</label><input id="kpcName"><label>E-mail</label><input id="kpcEmail" type="email"><label>Mot de passe (6 caractères minimum)</label><input id="kpcPassword" type="password"><button id="kpcSignupGo">Créer mon compte</button> <button id="kpcBack">Retour</button><p id="kpcMsg" class="err"></p>');$('kpcBack').onclick=login;$('kpcSignupGo').onclick=async()=>{let msg=$('kpcMsg');msg.textContent='Création…';try{let n=$('kpcName').value.trim(),email=$('kpcEmail').value.trim(),password=$('kpcPassword').value;if(!n)throw Error('Indique ton pseudo ou ton nom.');if(!email)throw Error('Indique ton adresse e-mail.');if(password.length<6)throw Error('Le mot de passe doit contenir au moins 6 caractères.');let x=await api('/auth/v1/signup',{method:'POST',body:JSON.stringify({email,password,data:{display_name:n}})});if(x?.access_token)store(x);modal('<h2>Compte créé ✅</h2><p>Ton compte est maintenant en attente de validation par un administrateur KPC.</p><button id="kpcReturn">Retour à la connexion</button>');$('kpcReturn').onclick=()=>{localStorage.removeItem(S);session=null;login()}}catch(x){msg.textContent=x.message}}}function login(){modal('<h2>KPC Mental Game</h2><p>Connecte-toi avec ton compte KPC.</p><label>E-mail</label><input id="kpcEmail" type="email"><label>Mot de passe</label><input id="kpcPassword" type="password"><button id="kpcLoginGo">Se connecter</button> <button id="kpcNew">Créer un compte</button><p id="kpcMsg" class="err"></p>');$('kpcNew').onclick=signup;$('kpcLoginGo').onclick=async()=>{let msg=$('kpcMsg');msg.textContent='Connexion…';try{store(await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:$('kpcEmail').value.trim(),password:$('kpcPassword').value})}));await approved();close();integrate()}catch(x){msg.textContent=x.message}}}function logout(){session=prof=null;localStorage.removeItem(S);login()}function snapshot(){if(typeof window.kpcDraftSnapshot==='function')return window.kpcDraftSnapshot();return{fields:[...document.querySelectorAll('input,select,textarea')].filter(x=>x.id||x.name).map(x=>({id:x.id,name:x.name,value:x.value,checked:x.checked,type:x.type}))}}function restore(d){if(typeof window.kpcRestoreDraft==='function')return window.kpcRestoreDraft(d);for(let f of d?.fields||[]){let q=f.id?$(f.id):document.querySelector('[name="'+CSS.escape(f.name)+'"]');if(q){if(/checkbox|radio/.test(f.type))q.checked=!!f.checked;else q.value=f.value??''}}}async function cloudSave(){try{await approved();let d=snapshot(),title='Main '+new Date().toLocaleString();await api('/rest/v1/mental_game_hands',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({user_id:session.user.id,title,hand_data:d,played_at:new Date().toISOString()})});return true}catch(x){console.warn('KPC cloud save:',x.message);return false}}async function list(){try{await approved();let a=await api('/rest/v1/mental_game_hands?select=id,title,hand_data,played_at,review_status&user_id=eq.'+encodeURIComponent(session.user.id)+'&order=played_at.desc');modal('<h2>Mes mains sauvegardées</h2>'+(a.length?a.map((h,i)=>'<div class="hand"><b>'+e(h.title||'Main sans titre')+'</b><div class="muted">'+e(new Date(h.played_at).toLocaleString())+'</div><button data-open="'+i+'">Ouvrir</button> <button data-del="'+e(h.id)+'">Supprimer</button></div>').join(''):'<p>Aucune main enregistrée.</p>')+'<br><button id="kpcClose">Fermer</button>');$('kpcClose').onclick=close;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{restore(a[+b.dataset.open].hand_data);close()});document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(confirm('Supprimer cette main ?')){await api('/rest/v1/mental_game_hands?id=eq.'+encodeURIComponent(b.dataset.del)+'&user_id=eq.'+encodeURIComponent(session.user.id),{method:'DELETE'});list()}})}catch(x){alert(x.message)}}async function users(){try{await approved();if(prof.role!=='admin')throw Error('Accès administrateur requis.');let a=await api('/rest/v1/profiles?select=id,display_name,approved,role&order=display_name.asc');modal('<h2>Gestion des comptes</h2>'+a.map(u=>'<div class="user"><b>'+e(u.display_name||'Sans nom')+'</b> — '+(u.approved?'Validé':'En attente')+(u.id===session.user.id?' (vous)':u.role!=='admin'?' <button data-user="'+e(u.id)+'">'+(u.approved?'Suspendre':'Valider')+'</button>':'')+'</div>').join('')+'<br><button id="kpcClose">Fermer</button>');$('kpcClose').onclick=close;document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{let u=a.find(z=>z.id===b.dataset.user);if(!u)return;await api('/rest/v1/profiles?id=eq.'+encodeURIComponent(u.id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({approved:!u.approved})});users()})}catch(x){alert(x.message)}}function integrate(){document.querySelectorAll('#kpcV22Bar').forEach(x=>x.remove());let ib=$('installBtn');if(ib)ib.style.display='none';let hands=document.querySelector('.bottom-nav .nav-btn[data-view="hands"]');if(hands&&!hands.dataset.kpcLabel){hands.dataset.kpcLabel='1';for(let n of hands.childNodes){if(n.nodeType===3&&n.textContent.trim()==='Mains')n.textContent='Mes mains'}}if(typeof window.saveHand==='function'&&!window.saveHand.__kpcCloud){let orig=window.saveHand;let wrapped=function(){let r=orig.apply(this,arguments);setTimeout(()=>cloudSave(),0);return r};wrapped.__kpcCloud=true;window.saveHand=wrapped}window.kpcV22Users=users;window.kpcV22Logout=logout;window.kpcV22CloudHands=list;if(typeof window.openModal==='function'){window.openMoreMenu=function(){let admin=prof?.role==='admin'?'<button class="secondary full" onclick="closeModal();kpcV22Users()">👥 Gestion des comptes</button>':'';openModal('<div class="modal-head"><div><span class="eyebrow">KPC Mental Game</span><h2>Plus</h2></div><button class="icon-btn" onclick="closeModal()">✕</button></div><button class="secondary full" onclick="closeModal();navigate(\'journal\')">✎ Journal mental</button><button class="secondary full" onclick="closeModal();navigate(\'stats\')">▥ Sauvegarde & progression</button><button class="secondary full" onclick="closeModal();openCoachMode()">♚ Mode Coach</button><button class="secondary full" onclick="closeModal();kpcV22CloudHands()">🂡 Mes mains sauvegardées</button>'+admin+'<button class="secondary full" onclick="closeModal();kpcV22Logout()">⇥ Déconnexion</button>')}} }async function init(){try{session=JSON.parse(localStorage.getItem(S)||'null')}catch{}if(!session?.access_token){login();return}try{await approved();integrate()}catch(x){if(x.message.includes('attente')){modal('<h2>Compte en attente ⏳</h2><p>Un administrateur KPC doit encore valider ton compte.</p><button id="kpcRetry">Réessayer</button> <button id="kpcLogout">Déconnexion</button>');$('kpcRetry').onclick=init;$('kpcLogout').onclick=logout}else login()}}function boot(){if(document.body)init();else document.addEventListener('DOMContentLoaded',init,{once:true})}boot()})();</script>'''
s=s.replace('</head>',css+'</head>',1) if '</head>' in s else css+s
s=s.replace('</body>',js+'</body>',1) if '</body>' in s else s+js
p.write_text(s,encoding='utf-8')
print('KPC V2.2 native UI integration applied')
